import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-roster-config.json"), "utf8"),
);
const kinds = Object.keys(contract.kinds);
const models = emitModels(contract.models, "rosterConfigKindSchema");
let go =
  '// Code generated by scripts/generate-workforce-roster-config.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var rosterConfigKinds=[]string{${kinds.map((k) => JSON.stringify(k)).join(",")}}\n`;
let ts =
  '// Generated by scripts/generate-workforce-roster-config.mjs.\nimport { z } from "zod";\n\n';
ts += `export const ROSTER_CONFIG_KINDS=${JSON.stringify(contract.kinds)} as const;\nexport const rosterConfigKindSchema=z.enum(${JSON.stringify(kinds)});\n`;
ts += `export const ROSTER_AUTO_POPULATION=${JSON.stringify(contract.auto_population)} as const;\n`;
ts += `export const ROSTER_STATUS=${JSON.stringify(contract.roster_status)} as const;\nexport const ROSTER_MODES=${JSON.stringify(contract.roster_modes)} as const;\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/roster_config_types.go",
  go + models.go,
  "packages/api/src/roster-config-contract.ts",
  ts + models.ts,
  "roster",
);
